commands.command:
node -e '
const d=require("./data/signals/query_class_occupancy.json");
const pad=(s,n)=>String(s).padEnd(n);
console.log(pad("query",44),pad("slots",6),pad("open",6),pad("incumb",7),pad("instit",7),pad("unclass",8),pad("published",10));
for(const p of d.probes) console.log(pad(p.query.slice(0,42),44),pad(p.slots_read,6),pad(p.open_share,6),pad(p.incumbent_slots,7),pad(p.institutional_slots,7),pad(p.unclassifiable_slots,8),pad(p.citation_occupancy===null?"WITHHELD":p.citation_occupancy,10));
const s=d.summary;
console.log("\nSLOTS:",JSON.stringify(s.slots_by_kind));
console.log("UNCLASSIFIABLE:",s.unclassifiable_slots,"of",s.slots_read_total,"slots ("+s.unclassifiable_slot_share+") - counted CLOSED, never open");
console.log("\nCONTROLS:",JSON.stringify(d.control_check.separation));
console.log("SIGNAL STATUS:",d.signal_status.published?"PUBLISHED":"WITHHELD - "+d.signal_status.reason);
if(!d.signal_status.published) console.log(d.signal_status.note);
if(d.discarded_probes.length) console.log("\nDISCARDED (channel degraded, not zero):",d.discarded_probes.map(x=>x.query).join(" | "));
'
